// stores/posts.js
import { defineStore } from 'pinia';
import { ref } from 'vue';

// // 模拟的 API 函数 (我们从 index.vue 把它“搬”到这里)
const fetchMockData = (page = 1, limit = 10) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const data = [];
      if (page > 4) {
        resolve({ list: [], hasMore: false });
        return;
      }
      for (let i = 0; i < limit; i++) {
        const id = (page - 1) * limit + i;
        if (id >= 35) break;
       // stores/posts.js -> fetchMockData 函数
       // ...
       data.push({
         id: id,
         community: 'r/programming',
         // ...
         upvotes: Math.floor(Math.random() * 500),
         comments: Math.floor(Math.random() * 100),
         isUpvoted: false // ⬅️ [添加] 默认未点赞
       });
       // ...
      }
      resolve({ list: data, hasMore: data.length > 0 && page < 4 });
    }, 800);
  });
};

// --- 定义 Store ---
export const usePostStore = defineStore('posts', () => {
  // --- State ---
  const posts = ref([]);
  const currentPage = ref(1);
  const loadingStatus = ref('more'); // 'loading', 'more', 'no-more'

  // 这是为“创建”功能预留的状态
  // 记住用户在“创建页”选择了哪个社区
  const selectedCommunityForPost = ref(null);

  // --- Actions ---

  /**
   * 获取帖子
   */
  async function fetchPosts(isRefresh = false) {
    if (loadingStatus.value === 'loading' && !isRefresh) return;

    if (isRefresh) {
      currentPage.value = 1;
      posts.value = [];
      loadingStatus.value = 'more';
    }

    if (loadingStatus.value === 'no-more') return;

    loadingStatus.value = 'loading';

    try {
      const res = await fetchMockData(currentPage.value);
      // 使用 .push(...res.list) 而非 [... , ... ] 来提高性能
      posts.value.push(...res.list); 

      if (res.hasMore) {
        loadingStatus.value = 'more';
        currentPage.value++;
      } else {
        loadingStatus.value = 'no-more';
      }
    } catch (error) {
      console.error("获取数据失败", error);
      loadingStatus.value = 'more';
    }
  }

  /**
   * (新) 添加一个新帖子
   */
 // stores/posts.js -> addNewPost 函数
 // ...
 function addNewPost(postData) {
   // 在 unshift 之前，为 postData 添加新属性
   postData.isUpvoted = false; // ⬅️ [添加] 新帖子默认未点赞
 
   posts.value.unshift(postData);
 }
 // stores/posts.js
 
 // ... (在 addNewPost 函数之后，return 之前) ...
 
 /**
  * (新) 切换帖子的点赞状态
  */
 function toggleUpvote(postId) {
   // 1. 在 posts 数组中找到这个帖子
   const post = posts.value.find(p => p.id === postId);
 
   if (post) {
     // 2. 检查它当前的点赞状态
     if (post.isUpvoted) {
       // 已经赞过了 -> 取消赞
       post.upvotes -= 1;
       post.isUpvoted = false;
     } else {
       // 还没赞 -> 点赞
       post.upvotes += 1;
       post.isUpvoted = true;
       // (在真实项目中，这里还会检查是否点过“踩”)
     }
   }
 }
 
  // --- Return ---
  return {
    posts,
    loadingStatus,
    selectedCommunityForPost,

    fetchPosts,
    addNewPost,
	toggleUpvote
  };
});